// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {EnumerableMap} from "@openzeppelin/contracts/utils/structs/EnumerableMap.sol";

import {CoreRoles} from "@libraries/CoreRoles.sol";
import {OutlandVault} from "@integrations/outland/OutlandVault.sol";

import {PortalBase} from "@integrations/outland/portals/PortalBase.sol";
import {OutlandMsgCodec} from "@integrations/outland/OutlandMsgCodec.sol";
import {IOutlandConnector} from "@interfaces/IOutlandPortal.sol";

/// @title PortalHub
/// @notice Main hub portal contract on Ethereum mainnet for managing cross-chain vault operations
/// @dev Manages multiple OutlandVaults for different chains and handles cross-chain token transfers and asset updates
contract PortalHub is PortalBase {
    using SafeERC20 for ERC20;
    using EnumerableMap for EnumerableMap.UintToAddressMap;
    using EnumerableMap for EnumerableMap.AddressToAddressMap;

    event VaultSet(uint256 timestamp, uint256 chainId, address indexed vault);
    event KeyValueSent(uint256 timestamp, uint256 chainId, uint256 nonce, bytes32 key, bytes32 value, address sender);
    event AssetMappingSet(uint256 timestamp, uint256 chainId, address indexed hubAsset, address indexed outpostAsset);
    event AssetsUpdateReceived(
        uint256 indexed timestamp,
        uint256 chainId,
        uint256 totalAssets,
        uint256 receiptTokenTotalSupply,
        uint256 stakedTokenTotalSupply
    );

    /// @notice Maps chainId to vault address for each supported chain
    EnumerableMap.UintToAddressMap vaults;

    /// @notice Maps chainId to asset registry (hub asset => chain asset)
    /// @dev Helpful when token addresses are not the same over multiple chains
    mapping(uint256 chainId => EnumerableMap.AddressToAddressMap) assetMapping;

    constructor() PortalBase(address(1), 1) {}

    function init(address _core, uint256 _hubChainId) external {
        require(address(core()) == address(0), AlreadyInitialized());
        chainId = _hubChainId;
        _setCore(_core);
    }

    /// ============================================================
    /// Vault Management
    /// ============================================================

    function setVault(address _vault) external onlyCoreRole(CoreRoles.PROTOCOL_PARAMETERS) {
        require(_vault != address(0), InvalidVault(_vault));
        uint256 chainId = OutlandVault(_vault).chainId();
        vaults.set(chainId, _vault);
        emit VaultSet(block.timestamp, chainId, _vault);
    }

    /// @notice Returns the vault address for a given chain
    /// @param _chainId The chain ID to query
    /// @return The vault address for the specified chain
    function getVault(uint256 _chainId) public view returns (address) {
        return vaults.get(_chainId);
    }

    /// @notice Returns all chain IDs that have registered vaults
    /// @return Array of chain IDs with registered vaults
    function getVaultChainIds() external view returns (uint256[] memory) {
        return vaults.keys();
    }

    /// ============================================================
    /// Asset Registry Management
    /// ============================================================

    /// @notice Configures mapping of assets between this chain and other chains
    /// @dev To be used in case when token addresses are different between chains
    /// @dev Creates bidirectional mapping: hubAsset <-> outpostAsset
    /// @param _chainId The chain ID for which to set the asset mapping
    /// @param _hubAsset The asset token address on the hub (mainnet)
    /// @param _outpostAsset The asset token address on the outpost
    function setAssetMapping(uint256 _chainId, address _hubAsset, address _outpostAsset)
        external
        onlyCoreRole(CoreRoles.PROTOCOL_PARAMETERS)
    {
        assetMapping[_chainId].set(_hubAsset, _outpostAsset);
        assetMapping[_chainId].set(_outpostAsset, _hubAsset);
        emit AssetMappingSet(block.timestamp, _chainId, _hubAsset, _outpostAsset);
    }

    /// @notice Returns the mapped asset address for a given chain and asset
    /// @param _chainId The chain ID to query
    /// @param _asset The asset token address to look up
    /// @return The corresponding asset address on the target chain
    function getAssetMapping(uint256 _chainId, address _asset) external view returns (address) {
        return assetMapping[_chainId].get(_asset);
    }

    /// ============================================================
    /// Sender side
    /// ============================================================

    /// @notice Sends tokens from the hub to an outpost chain
    /// @dev Withdraws tokens from vault, approves connector, and initiates cross-chain transfer
    /// @dev Can only be called by OUTLAND_KEEPER role
    /// @param _chainId The destination chain ID
    /// @param _token The token address to send
    /// @param _amount The amount of tokens to send
    /// @param _connector The authorized connector address
    function sendTokens(uint256 _chainId, address _token, uint256 _amount, address payable _connector)
        external
        payable
        whenNotPaused
        onlyCoreRole(CoreRoles.OUTLAND_KEEPER)
    {
        require(_amount > 0, InvalidAmount(_amount));
        require(vaults.contains(_chainId), ChainNotSupported(_chainId));
        require(assetMapping[_chainId].contains(_token), InvalidAsset(_token));
        require(isConnector(_connector), InvalidSender(_connector));

        TransferPayload memory payload = TransferPayload({
            selector: OutlandMsgCodec.TRANSFER,
            chainId: chainId,
            nonce: _nextOutboundNonce(_chainId),
            assetToken: assetMapping[_chainId].get(_token),
            amount: _amount
        });

        address vault = vaults.get(_chainId);
        OutlandVault(vault).portalWithdraw(_token, _amount);

        ERC20(_token).forceApprove(_connector, _amount);
        IOutlandConnector(_connector).sendTokens{value: msg.value}(_chainId, _token, _amount, abi.encode(payload));

        emit TokensSent(block.timestamp, _chainId, payload.nonce, _token, _amount, _connector);
    }

    /// @notice Forwards arbitrary key-value pairs to an outpost chain
    /// @dev Used to propagate mainnet rates and configuration to L2 consumers (e.g. OutlandGatewayL2)
    /// @dev Can only be called by OUTLAND_KEYVALUE_SENDER role
    /// @param _chainId Destination outpost chain ID
    /// @param _key Key identifier
    /// @param _value Value for the key
    /// @param _connector Authorized connector address
    function sendKeyValue(uint256 _chainId, bytes32 _key, bytes32 _value, address payable _connector)
        external
        payable
        whenNotPaused
        onlyCoreRole(CoreRoles.OUTLAND_KEYVALUE_SENDER)
    {
        require(vaults.contains(_chainId), ChainNotSupported(_chainId));
        require(isConnector(_connector), InvalidSender(_connector));

        KeyValuePayload memory payload = KeyValuePayload({
            selector: OutlandMsgCodec.KEY_VALUE,
            chainId: chainId,
            nonce: _nextOutboundNonce(_chainId),
            key: _key,
            value: _value,
            sentAt: block.timestamp
        });

        IOutlandConnector(_connector).sendMessage{value: msg.value}(_chainId, abi.encode(payload));

        emit KeyValueSent(block.timestamp, _chainId, payload.nonce, _key, _value, _connector);
    }

    // call internal _handleSendTokenBridge with _pullFromSender = true
    function _handleSendTokenBridge(
        uint256 _targetChainId,
        address _token,
        uint256 _amount,
        address _recipient,
        address payable _connector
    ) internal override {
        _handleSendTokenBridge(_targetChainId, _token, _amount, _recipient, _connector, true);
    }

    /// @dev Bridging tokens L1 -> L2
    /// @param _chainId The destination chain ID
    /// @param _token The L1 iUSD or siUSD token address
    /// @param _amount The amount of tokens to bridge
    /// @param _recipient The recipient on the destination chain
    /// @param _connector The connector to use to relay the message
    /// @param _pullFromSender When false, tokens are assumed to already sit in the destination vault
    function _handleSendTokenBridge(
        uint256 _chainId,
        address _token,
        uint256 _amount,
        address _recipient,
        address _connector,
        bool _pullFromSender
    ) internal {
        require(vaults.contains(_chainId), ChainNotSupported(_chainId));
        OutlandVault vault = OutlandVault(vaults.get(_chainId));
        require(_token == vault.stakedToken() || _token == vault.receiptToken(), InvalidBridgedToken(_token));
        require(assetMapping[_chainId].contains(_token), InvalidAsset(_token));

        if (_pullFromSender) {
            ERC20(_token).safeTransferFrom(msg.sender, address(vault), _amount);
        }

        TokenBridgePayload memory payload = TokenBridgePayload({
            selector: OutlandMsgCodec.TOKEN_BRIDGE,
            chainId: chainId,
            nonce: _nextOutboundNonce(_chainId),
            token: assetMapping[_chainId].get(_token),
            amount: _amount,
            recipient: _recipient,
            destinationChainId: _chainId,
            totalAssetsValue: 0,
            receiptTokenTotalSupply: 0,
            stakedTokenTotalSupply: 0
        });
        IOutlandConnector(_connector).sendMessage{value: _pullFromSender ? msg.value : 0}(_chainId, abi.encode(payload));

        emit BridgedTokensSent(block.timestamp, _chainId, payload.nonce, _token, _amount, _connector);
    }

    /// ============================================================
    /// Receiver side
    /// ============================================================

    function _validateInboundEnvelope(uint256 _chainId, bytes calldata _data) internal view override {
        super._validateInboundEnvelope(_chainId, _data);
        require(vaults.contains(_chainId), ChainNotSupported(_chainId));
    }

    function _executeInboundMessage(uint256 _chainId, address _connector, bytes calldata _data) internal override {
        bytes1 messageType = OutlandMsgCodec.getMessageType(_data);

        if (messageType == OutlandMsgCodec.TRANSFER) {
            _handleReceiveTokenTransfer(_chainId, _connector, _data);
        } else if (messageType == OutlandMsgCodec.MESSAGE) {
            _handleReceiveAssetsUpdate(_chainId, _data);
        } else if (messageType == OutlandMsgCodec.TOKEN_BRIDGE) {
            _handleReceiveTokenBridge(_chainId, _connector, _data);
        }
    }

    /// @notice Internal handler for receiving token transfers from outpost chains
    /// @dev Pulls assets from receiver, approves vault, and deposits to the vault
    function _handleReceiveTokenTransfer(uint256 _chainId, address _connector, bytes calldata _data) internal {
        require(isConnector(_connector), InvalidReceiver(_connector));
        (address senderToken, uint256 amount) = OutlandMsgCodec.getTransferPayload(_data);
        address token = assetMapping[_chainId].get(senderToken);
        require(token != address(0), InvalidAsset(senderToken));

        OutlandVault vault = OutlandVault(vaults.get(_chainId));
        IOutlandConnector(_connector).pullAssets(token, amount);

        ERC20(token).forceApprove(address(vault), amount);
        vault.portalDeposit(token, amount);
        emit TokensReceived(block.timestamp, _chainId, token, amount, _connector);
    }

    /// @notice Internal handler for receiving asset updates from outpost chains
    /// @dev Updates the vault with the latest total assets from the outpost chain
    function _handleReceiveAssetsUpdate(uint256 _chainId, bytes calldata _data) internal {
        (uint256 totalAssetsValue, uint256 receiptTokenTotalSupply, uint256 stakedTokenTotalSupply) =
            OutlandMsgCodec.getAssetsUpdatePayload(_data);

        OutlandVault(vaults.get(_chainId))
            .portalUpdate(totalAssetsValue, receiptTokenTotalSupply, stakedTokenTotalSupply);
        emit AssetsUpdateReceived(
            block.timestamp, _chainId, totalAssetsValue, receiptTokenTotalSupply, stakedTokenTotalSupply
        );
    }

    /// @notice Internal handler for receiving bridged iUSD / siUSD from an outpost chain
    /// if destinationChainId == chainId, this is a L2 -> L1 bridging
    /// else, this is a L2 -> L2 bridging and the message needs to be relayed to another outpost
    /// @dev L2 -> L1: withdraws tokens from the source vault to the recipient
    /// @dev L2 -> L2: moves tokens to the destination vault and relays a mint message to the target outpost
    function _handleReceiveTokenBridge(uint256 _sourceChainId, address _connector, bytes calldata _data) internal {
        require(isConnector(_connector), InvalidReceiver(_connector));

        address token;
        uint256 amount;
        address recipient;
        uint256 destinationChainId;
        {
            address senderToken;
            uint256 totalAssetsValue;
            uint256 receiptTokenTotalSupply;
            uint256 stakedTokenTotalSupply;
            (
                senderToken,
                amount,
                recipient,
                destinationChainId,
                totalAssetsValue,
                receiptTokenTotalSupply,
                stakedTokenTotalSupply
            ) = OutlandMsgCodec.getTokenBridgePayload(_data);
            token = assetMapping[_sourceChainId].get(senderToken);
            require(token != address(0), InvalidAsset(senderToken));

            // Outpost-originated bridge messages carry pre-burn L2 supplies; portalUpdate runs before release.
            OutlandVault(vaults.get(_sourceChainId))
                .portalUpdate(totalAssetsValue, receiptTokenTotalSupply, stakedTokenTotalSupply);
        }

        // L2 -> L1 bridging
        if (destinationChainId == chainId) {
            // simply release the tokens from the source vault to the recipient
            OutlandVault(vaults.get(_sourceChainId)).portalBridgeWithdraw(token, amount, recipient);
        }
        // L2 -> L2 bridging
        else {
            // we shall release the tokens from the source vault to the destination vault
            if (!vaults.contains(destinationChainId)) {
                // if the destination vault does not exist, do not move the tokens, and
                // send a message back to the source outpost so the user gets their tokens back.
                _handleSendTokenBridge(_sourceChainId, token, amount, recipient, _connector, false);
            } else {
                // if the destination vault exists, release the tokens from source to destination vault
                // and send a message to the destination outpost to mint the tokens to the recipient
                address destinationVault = vaults.get(destinationChainId);
                OutlandVault(vaults.get(_sourceChainId)).portalBridgeWithdraw(token, amount, destinationVault);
                _handleSendTokenBridge(destinationChainId, token, amount, recipient, _connector, false);
            }
        }

        emit BridgedTokensReceived(block.timestamp, _sourceChainId, token, amount, recipient);
    }
}

