// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

import {CoreRoles} from "@libraries/CoreRoles.sol";
import {CoreControlled} from "@core/CoreControlled.sol";
import {OutlandMsgCodec} from "@integrations/outland/OutlandMsgCodec.sol";
import {IOutlandPortal, IOutlandConnector} from "@interfaces/IOutlandPortal.sol";

/// @title PortalBase
/// @notice Base contract for portal contracts with common connector logic
/// @dev Provides shared functionality for managing multiple connectors
abstract contract PortalBase is CoreControlled, IOutlandPortal {
    using EnumerableSet for EnumerableSet.AddressSet;

    /// @notice The chain ID where this portal operates
    uint256 public chainId;

    /// @notice Set of authorized addresses that can send cross-chain messages
    EnumerableSet.AddressSet internal connectors;

    /// @notice Outbound nonce per destination chain, incremented on every sent message
    mapping(uint256 targetChainId => uint256 nonce) public outboundNonce;

    /// @notice Queued inbound message hashes keyed by source chain and message nonce
    mapping(uint256 sourceChainId => mapping(uint256 nonce => bytes32 dataHash)) internal inboundHashes;

    /// @notice Next inbound nonce to process per source chain (0 means the next expected nonce is 1)
    mapping(uint256 sourceChainId => uint256 nonce) public inboundNonce;

    /// @notice When true, user-initiated bridging is disabled independently of the global pause
    bool public bridgePaused;

    error AlreadyInitialized();
    error InvalidBridgedToken(address _token);
    error InvalidAsset(address _asset);
    error InvalidVault(address _vault);
    error InvalidAmount(uint256 _amount);
    error InvalidSender(address _sender);
    error InvalidChainId(uint256 _chainId, uint256 _decodedChainId);
    error InvalidReceiver(address _receiver);
    error ChainNotSupported(uint256 _chainId);
    error InvalidNonce(uint256 _nonce);
    error DuplicateInboundMessage(uint256 _sourceChainId, uint256 _nonce);
    error InvalidInboundNonce(uint256 _nonce, uint256 _expectedNonce);
    error InboundMessageNotQueued(uint256 _sourceChainId, uint256 _nonce);
    error InvalidQueuedData();
    error InvalidInboundNonceTarget(uint256 _newNonce);
    error BridgeOperationsPaused();

    error ZeroAddress();
    error EntryNotFound(address _entry);
    error DuplicateEntry(address _entry);

    event TokensSent(
        uint256 indexed timestamp, uint256 chainId, uint256 nonce, address token, uint256 amount, address sender
    );
    event TokensReceived(uint256 indexed timestamp, uint256 chainId, address token, uint256 amount, address receiver);
    event BridgedTokensSent(
        uint256 indexed timestamp, uint256 chainId, uint256 nonce, address token, uint256 amount, address sender
    );
    event BridgedTokensReceived(
        uint256 indexed timestamp, uint256 chainId, address token, uint256 amount, address receiver
    );

    event ConnectorAdded(uint256 indexed timestamp, address connector);
    event ConnectorRemoved(uint256 indexed timestamp, address connector);
    event MessageQueued(uint256 indexed sourceChainId, uint256 indexed nonce, address indexed connector, bytes data);
    event MessageProcessed(uint256 indexed sourceChainId, uint256 indexed nonce);
    event InboundNonceSet(uint256 indexed sourceChainId, uint256 oldNonce, uint256 newNonce);
    event OutboundNonceSet(uint256 indexed targetChainId, uint256 oldNonce, uint256 newNonce);
    event BridgePaused(uint256 indexed timestamp);
    event BridgeUnpaused(uint256 indexed timestamp);

    uint256[100] private __gap;

    /// @notice Initializes the PortalBase contract
    /// @param _core Address of the Core contract for role management
    /// @param _chainId Chain ID where this portal operates
    constructor(address _core, uint256 _chainId) CoreControlled(_core) {
        chainId = _chainId;
    }

    modifier whenNotBridgePaused() {
        require(!bridgePaused, BridgeOperationsPaused());
        _;
    }

    /// @notice Disables user-initiated bridging while leaving other portal operations available
    function pauseBridge() external onlyCoreRole(CoreRoles.PAUSE) {
        bridgePaused = true;
        emit BridgePaused(block.timestamp);
    }

    /// @notice Re-enables user-initiated bridging
    function unpauseBridge() external onlyCoreRole(CoreRoles.UNPAUSE) {
        bridgePaused = false;
        emit BridgeUnpaused(block.timestamp);
    }

    /// @notice Returns the queued message hash for a source chain and nonce, if any
    function getInboundMessageHash(uint256 _sourceChainId, uint256 _nonce) external view returns (bytes32) {
        return inboundHashes[_sourceChainId][_nonce];
    }

    /// @notice Returns the next inbound nonce expected for processing on a source chain
    function getExpectedInboundNonce(uint256 _sourceChainId) public view returns (uint256) {
        uint256 nextNonce = inboundNonce[_sourceChainId];
        return nextNonce == 0 ? 1 : nextNonce;
    }

    /// @inheritdoc IOutlandPortal
    function receiveMessage(uint256 _chainId, bytes calldata _data) external {
        require(isConnector(msg.sender), InvalidSender(msg.sender));
        _validateInboundEnvelope(_chainId, _data);

        uint256 nonce = OutlandMsgCodec.getNonce(_data);
        require(nonce > 0, InvalidNonce(nonce));
        require(inboundHashes[_chainId][nonce] == bytes32(0), DuplicateInboundMessage(_chainId, nonce));

        inboundHashes[_chainId][nonce] = keccak256(_data);
        emit MessageQueued(_chainId, nonce, msg.sender, _data);
    }

    /// @inheritdoc IOutlandPortal
    function processMessage(uint256 _chainId, bytes calldata _data, address _connector)
        external
        whenNotPaused
        onlyCoreRole(CoreRoles.OUTLAND_KEEPER)
    {
        uint256 nonce = OutlandMsgCodec.getNonce(_data);
        uint256 expectedNonce = getExpectedInboundNonce(_chainId);
        require(nonce == expectedNonce, InvalidInboundNonce(nonce, expectedNonce));

        bytes32 dataHash = inboundHashes[_chainId][nonce];
        require(dataHash != bytes32(0), InboundMessageNotQueued(_chainId, nonce));
        require(keccak256(_data) == dataHash, InvalidQueuedData());

        _executeInboundMessage(_chainId, _connector, _data);

        delete inboundHashes[_chainId][nonce];
        inboundNonce[_chainId] = nonce + 1;
        emit MessageProcessed(_chainId, nonce);
    }

    /// @notice Sets the next inbound nonce to process for a source chain
    function setInboundNonce(uint256 _sourceChainId, uint256 _newNonce)
        external
        onlyCoreRole(CoreRoles.PROTOCOL_PARAMETERS)
    {
        require(_newNonce > 0, InvalidInboundNonceTarget(_newNonce));

        uint256 oldNonce = inboundNonce[_sourceChainId];
        inboundNonce[_sourceChainId] = _newNonce;
        emit InboundNonceSet(_sourceChainId, oldNonce, _newNonce);
    }

    /// @notice Sets the last assigned outbound nonce for a destination chain; the next send uses `_newNonce + 1`
    function setOutboundNonce(uint256 _targetChainId, uint256 _newNonce)
        external
        onlyCoreRole(CoreRoles.PROTOCOL_PARAMETERS)
    {
        uint256 oldNonce = outboundNonce[_targetChainId];
        outboundNonce[_targetChainId] = _newNonce;
        emit OutboundNonceSet(_targetChainId, oldNonce, _newNonce);
    }

    /// @dev Assigns and returns the next outbound nonce for a destination chain
    function _nextOutboundNonce(uint256 _targetChainId) internal returns (uint256 nonce) {
        nonce = ++outboundNonce[_targetChainId];
    }

    /// @dev Portal-specific validation of the inbound message envelope
    function _validateInboundEnvelope(uint256 _chainId, bytes calldata _data) internal view virtual {
        uint256 senderChainId = OutlandMsgCodec.getChainId(_data);
        require(_chainId == senderChainId, InvalidChainId(_chainId, senderChainId));
    }

    /// @dev Portal-specific execution of a validated inbound message
    function _executeInboundMessage(uint256 _chainId, address _connector, bytes calldata _data) internal virtual;

    function getSendTokensFee(uint256 _targetChainId, address _token, uint256 _amount, address payable _connector)
        external
        view
        returns (uint256)
    {
        TransferPayload memory payload = TransferPayload({
            selector: OutlandMsgCodec.TRANSFER, chainId: chainId, nonce: 0, assetToken: _token, amount: _amount
        });

        return IOutlandConnector(_connector).getSendTokensFee(_targetChainId, _token, _amount, abi.encode(payload));
    }

    /// @notice Quotes the cross-chain message fee for iUSD / siUSD bridging (both directions)
    function getBridgeMessageFee(uint256 _targetChainId, address payable _connector) external view returns (uint256) {
        return IOutlandConnector(_connector)
            .getMessageFee(
                _targetChainId,
                abi.encode(
                    TokenBridgePayload({
                    selector: OutlandMsgCodec.TOKEN_BRIDGE,
                    chainId: chainId,
                    nonce: 0,
                    token: address(0),
                    amount: 0,
                    recipient: address(0),
                    destinationChainId: _targetChainId,
                    totalAssetsValue: 0,
                    receiptTokenTotalSupply: 0,
                    stakedTokenTotalSupply: 0
                })
                )
            );
    }

    function getMessageFee(uint256 _targetChainId, uint256 _amount, address payable _connector)
        external
        view
        returns (uint256)
    {
        AssetsUpdatePayload memory payload = AssetsUpdatePayload({
            selector: OutlandMsgCodec.MESSAGE,
            chainId: chainId,
            nonce: 0,
            totalAssetsValue: _amount,
            receiptTokenTotalSupply: 0,
            stakedTokenTotalSupply: 0
        });

        return IOutlandConnector(_connector).getMessageFee(_targetChainId, abi.encode(payload));
    }

    /// @notice Add a new authorized connector
    /// @param _connector The address of the connector to add
    function addConnector(address _connector) external onlyCoreRole(CoreRoles.PROTOCOL_PARAMETERS) {
        require(_connector != address(0), ZeroAddress());
        require(connectors.add(_connector), DuplicateEntry(_connector));
        emit ConnectorAdded(block.timestamp, _connector);
    }

    /// @notice Remove an authorized connector
    /// @param _connector The address of the connector to remove
    function removeConnector(address _connector) external onlyCoreRole(CoreRoles.PROTOCOL_PARAMETERS) {
        require(connectors.remove(_connector), EntryNotFound(_connector));
        emit ConnectorRemoved(block.timestamp, _connector);
    }

    /// @notice Check if an address is an authorized connector
    function isConnector(address _connector) public view returns (bool) {
        return connectors.contains(_connector);
    }

    /// @notice Get all authorized connectors
    function getConnectors() public view returns (address[] memory) {
        return connectors.values();
    }

    /// @notice Get the number of authorized connectors
    function getConnectorsCount() public view returns (uint256) {
        return connectors.length();
    }

    /// @notice Bridges iUSD or siUSD to another chain with an assets report payload
    function bridge(
        uint256 _targetChainId,
        address _token,
        uint256 _amount,
        address _recipient,
        address payable _connector
    ) external payable whenNotPaused whenNotBridgePaused onlyCoreRole(CoreRoles.BRIDGE_INITIATOR) {
        require(_amount > 0, InvalidAmount(_amount));
        require(_recipient != address(0), ZeroAddress());
        require(isConnector(_connector), InvalidSender(_connector));

        _handleSendTokenBridge(_targetChainId, _token, _amount, _recipient, _connector);
    }

    /// @dev Hub and outpost implementations burn local tokens, snapshot accounting, and send a bridge message
    /// @dev must emit BridgedTokensSent event
    function _handleSendTokenBridge(
        uint256 _targetChainId,
        address _token,
        uint256 _amount,
        address _recipient,
        address payable _connector
    ) internal virtual;
}

