// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title OutlandMsgCodec
/// @notice Utility library for decoding cross-chain messages and payloads in the Outland system
/// @dev Wire layout: selector (32) | chainId (32) | nonce (32) | abi.encode(payload body)
library OutlandMsgCodec {
    error InvalidSize(uint256 _size);

    /// @notice Transport type identifier for general messages
    bytes1 internal constant MESSAGE = hex"00";

    /// @notice Transport type identifier for token transfers
    bytes1 internal constant TRANSFER = hex"01";

    /// @notice Transport type identifier for arbitrary hub-outpost key-value updates
    bytes1 internal constant KEY_VALUE = hex"02";

    /// @notice Transport type identifier for iUSD / siUSD bridging with an assets report
    bytes1 internal constant TOKEN_BRIDGE = hex"03";

    uint256 public constant HEADER_SIZE = 96;

    /// @notice Gets the message type from cross-chain message data
    function getMessageType(bytes calldata _data) internal pure returns (bytes1 messageType) {
        require(_data.length >= HEADER_SIZE, InvalidSize(_data.length));
        messageType = bytes1(_data[:32]);
    }

    /// @notice Gets the chain ID from cross-chain message data
    function getChainId(bytes calldata _data) internal pure returns (uint256 chainId) {
        require(_data.length >= HEADER_SIZE, InvalidSize(_data.length));
        chainId = uint256(bytes32(_data[32:64]));
    }

    /// @notice Gets the outbound nonce assigned by the sender portal
    function getNonce(bytes calldata _data) internal pure returns (uint256 nonce) {
        require(_data.length >= HEADER_SIZE, InvalidSize(_data.length));
        nonce = uint256(bytes32(_data[64:96]));
    }

    /// @notice Gets the transfer payload (recipient and amount) from cross-chain data
    function getTransferPayload(bytes calldata _data) internal pure returns (address, uint256) {
        require(_data.length >= HEADER_SIZE, InvalidSize(_data.length));
        return abi.decode(_data[HEADER_SIZE:], (address, uint256));
    }

    /// @notice Gets the assets update payload from cross-chain data
    function getAssetsUpdatePayload(bytes calldata _data) internal pure returns (uint256, uint256, uint256) {
        require(_data.length >= HEADER_SIZE, InvalidSize(_data.length));
        return abi.decode(_data[HEADER_SIZE:], (uint256, uint256, uint256));
    }

    /// @notice Gets the key-value payload from cross-chain data
    function getKeyValuePayload(bytes calldata _data)
        internal
        pure
        returns (bytes32 key, bytes32 value, uint256 sentAt)
    {
        require(_data.length >= HEADER_SIZE, InvalidSize(_data.length));
        (key, value, sentAt) = abi.decode(_data[HEADER_SIZE:], (bytes32, bytes32, uint256));
    }

    /// @notice Gets the token bridge payload from cross-chain data
    function getTokenBridgePayload(bytes calldata _data)
        internal
        pure
        returns (
            address token,
            uint256 amount,
            address recipient,
            uint256 destinationChainId,
            uint256 totalAssetsValue,
            uint256 receiptTokenTotalSupply,
            uint256 stakedTokenTotalSupply
        )
    {
        require(_data.length >= HEADER_SIZE, InvalidSize(_data.length));
        return abi.decode(_data[HEADER_SIZE:], (address, uint256, address, uint256, uint256, uint256, uint256));
    }
}

